export const LabelSchema = z.object({ id: z.uuid(), name: z.string().min(1).max(40), color: z.string().regex(/^#[0-9a-fA-F]{6}$/), createdAt: z.iso.datetime() });
export type Label = z.infer<typeof LabelSchema>;
