const labels = new Map<string, Label>();
const sortKey = (label: Label): string => `${label.createdAt}|${label.id}`;
export function listLabels(query: ListLabelsQuery): LabelPage { return paginate([...labels.values()], query, sortKey); }
export function getLabel(id: string): Label | undefined { return labels.get(id); }
export function createLabel(input: CreateLabel): Label { const label: Label = { id: randomUUID(), ...input, createdAt: new Date().toISOString() }; labels.set(label.id, label); return label; }

