labelsRouter.get('/v1/labels', (req, res) => { const query = ListLabelsQuerySchema.parse(req.query); res.json(LabelPageSchema.parse(listLabels(query))); });
labelsRouter.post('/v1/labels', idempotency(), (req, res) => { const label = createLabel(CreateLabelSchema.parse(req.body)); res.status(201).location(`/v1/labels/${label.id}`).json(LabelSchema.parse(label)); });
labelsRouter.get('/v1/labels/:labelId', (req, res) => { const { labelId } = LabelParamsSchema.parse(req.params); const label = getLabel(labelId); if (label === undefined) throw notFound(`label ${labelId} not found`); res.json(LabelSchema.parse(label)); });

